void ov74_02235B14(Sprite *sprite, Pokemon *mon, enum Species species, int form, u8 *buffer, PokemonSpriteTemplate *monSpriteTemplate) {
    MainMenuUtilManager *utilMan = &ov74_0223D454;

    enum Gender monGender = (enum Gender)(GetMonGender(mon));
    BOOL shiny = MonIsShiny(mon);

    GetMonSpriteCharAndPlttNarcIdsEx(monSpriteTemplate, species, monGender, 2, shiny, form, 0);

    u32 personality = GetMonData(mon, MON_DATA_PERSONALITY, 0L);
    sub_02014494((enum NarcID)(monSpriteTemplate->narcID), monSpriteTemplate->character, utilMan->heapID, 0, 0, 10, 10, buffer, personality, 0, 2, species);

    DC_FlushRange(buffer, ((8 * (8 / 2)) * (10 * 10)));

    NNSG2dImageProxy *imageProxy = Sprite_GetImageProxy(sprite);
    u32 imageLocation = NNS_G2dGetImageLocation(imageProxy, NNS_G2D_VRAM_TYPE_2DSUB);

    GXS_LoadOBJ(buffer, imageLocation + ((8 * (8 / 2)) * (10 * 10)), ((8 * (8 / 2)) * (10 * 10)));
    NNSG2dImagePaletteProxy *plttProxy = Sprite_GetPaletteProxy(sprite);
    u32 plttLocation = NNS_G2dGetImagePaletteLocation(plttProxy, NNS_G2D_VRAM_TYPE_2DSUB);

    GfGfxLoader_GXLoadPal((enum NarcID)(monSpriteTemplate->narcID), monSpriteTemplate->palette, PAL_LOAD_SUB_OBJ, ((3) * ((16) * sizeof(u16))) + plttLocation, ((16) * sizeof(u16)), utilMan->heapID);
}
